# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">CUMHURİYET DÖNEMİ\'NDE MİLLÎ EDEBİYAT ANLAYIŞINI YANSITAN ŞİİR (1923–1960)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Biçim, Dil ve Ahenk Özellikleri</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kaynak:</tspan> Ziya Gökalp, Mehmet Emin</text>\n  <text x="40" y="107" font-size="10.5" fill="#1e3a8a">Yurdakul ve <tspan font-weight="bold">Beş Hececiler</tspan> ile başlayan</text>\n  <text x="40" y="122" font-size="10.5" fill="#1e3a8a">Millî Edebiyat akımının Cumhuriyet\'teki devamıdır.</text>\n  <text x="32" y="143" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Ölçü ve Nazım Birimi:</tspan> Halk şiiri geleneğine</text>\n  <text x="40" y="158" font-size="10.5" fill="#1e3a8a">uygun olarak <tspan font-weight="bold">hece ölçüsü</tspan> (7, 8, 11, 14\'lü)</text>\n  <text x="40" y="173" font-size="10.5" fill="#1e3a8a">ve <tspan font-weight="bold">dörtlük</tspan> (koşma, türkü biçimleri) esas alındı</text>\n  <text x="40" y="188" font-size="10" fill="#1e3a8a">(Zamanla serbest nazımla yazanlar da oldu).</text>\n  <text x="32" y="209" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Dil:</tspan> İstanbul Türkçesini esas alan <tspan font-weight="bold">sade,</tspan></text>\n  <text x="40" y="224" font-size="10.5" font-weight="bold" fill="#1d4ed8">duru, anlaşılır ve yaşayan halk Türkçesi.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Tema ve İçerik ("Memleket Edebiyatı")</text>\n  <text x="372" y="92" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Anadolu\'ya Yöneliş:</tspan> Anadolu coğrafyası,</text>\n  <text x="380" y="107" font-size="10.5" fill="#14532d">doğası, köylüsü, çobanı ve folkloru gerçekçi</text>\n  <text x="380" y="122" font-size="10.5" fill="#14532d">ve romantik-lirik bir duyarlılıkla işlendi.</text>\n  <text x="372" y="143" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Epik ve Hamasi Temalar:</tspan> Kurtuluş Savaşı,</text>\n  <text x="380" y="158" font-size="10.5" fill="#14532d">Atatürk devrimleri, Türk tarihi, Malazgirt,</text>\n  <text x="380" y="173" font-size="10.5" fill="#14532d">İstanbul\'un fethi, <tspan font-weight="bold">bayrak, vatan ve şehitlik.</tspan></text>\n  <rect x="372" y="186" width="296" height="42" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="203" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Yayın Organları: Çınaraltı, Hisar, Ülkü,</text>\n  <text x="520" y="218" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Kültür Haftası, Kopuz, Türk Yurdu dergileri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MEMLEKET EDEBİYATININ ÖNCÜ ŞAİRLERİ VE BAŞLICA ESERLERİ – I</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="67" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Ahmet Kutsi Tecer (1901–1967)</text>\n  <text x="30" y="90" font-size="10" fill="#78350f">• <tspan font-weight="bold">Kimliği:</tspan> Halk kültürü araştırmacısı;</text>\n  <text x="38" y="105" font-size="10" fill="#78350f"><tspan font-weight="bold">Âşık Veysel</tspan>\'i Türkiye\'ye tanıtan şair.</text>\n  <text x="30" y="126" font-size="10" fill="#78350f">• <tspan font-weight="bold">Ünlü Şiirleri:</tspan> <tspan font-weight="bold">"Orda Bir Köy Var</tspan></text>\n  <text x="38" y="141" font-size="10" fill="#78350f"><tspan font-weight="bold">Uzakta"</tspan>, <tspan font-weight="bold">"Nerdesin"</tspan>, "Halay".</text>\n  <text x="30" y="162" font-size="10" fill="#78350f">• <tspan font-weight="bold">Eserleri:</tspan> <tspan font-style="italic">Şiirler</tspan> · Tiyatro:</text>\n  <text x="38" y="177" font-size="10" font-style="italic" fill="#78350f">Koçyiğit Köroğlu, Köşebaşı,</text>\n  <text x="38" y="192" font-size="10" font-style="italic" fill="#78350f">Bir Pazar Günü, Satılık Ev.</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="350" y="67" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">Arif Nihat Asya (1904–1975)</text>\n  <text x="255" y="90" font-size="10" fill="#7f1d1d">• <tspan font-weight="bold">Unvanı:</tspan> <tspan font-weight="bold">"Bayrak Şairi"</tspan> (5 Ocak</text>\n  <text x="263" y="105" font-size="10" fill="#7f1d1d">Adana\'nın kurtuluşunda "Bayrak"ı yazdı).</text>\n  <text x="255" y="126" font-size="10" fill="#7f1d1d">• Hece, aruz ve serbest ölçüyü</text>\n  <text x="263" y="141" font-size="10" fill="#7f1d1d">kullandı; <tspan font-weight="bold">rubai</tspan> türünde ustalaştı.</text>\n  <text x="255" y="162" font-size="10" fill="#7f1d1d">• <tspan font-weight="bold">Şiirleri:</tspan> <tspan font-style="italic">Bir Bayrak Rüzgâr</tspan></text>\n  <text x="263" y="177" font-size="10" font-style="italic" fill="#7f1d1d">Bekliyor, Dualar ve Âminler, Kökler</text>\n  <text x="263" y="192" font-size="10" font-style="italic" fill="#7f1d1d">ve Dallar, Rubaiyyat-ı Ârif, Kıbrıs</text>\n  <text x="263" y="207" font-size="10" fill="#7f1d1d"><tspan font-style="italic">Rubaileri</tspan> ("Fetih Marşı").</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="67" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Kemalettin Kamu (1901–1948)</text>\n  <text x="480" y="90" font-size="10" fill="#581c87">• <tspan font-weight="bold">Unvanı:</tspan> <tspan font-weight="bold">"Gurbet Şairi"</tspan></text>\n  <text x="488" y="105" font-size="10" fill="#581c87">("Ben gurbette değilim / Gurbet</text>\n  <text x="488" y="120" font-size="10" fill="#581c87">benim içimde" dizeleriyle tanınır).</text>\n  <text x="480" y="141" font-size="10" fill="#581c87">• <tspan font-weight="bold">Başyapıtı:</tspan> Türk edebiyatının</text>\n  <text x="488" y="156" font-size="10" font-weight="bold" fill="#6b21a8">en ünlü pastoral şiirlerinden olan</text>\n  <text x="488" y="171" font-size="10" font-weight="bold" fill="#7e22ce">"Bingöl Çobanları"</text>\n  <text x="480" y="192" font-size="10" fill="#581c87">• Diğer şiirleri: "Gurbet", "İzmir",</text>\n  <text x="488" y="207" font-size="10" fill="#581c87">"Kimsesizlik", "İrşad".</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MİLLÎ EDEBİYAT ANLAYIŞINI SÜRDÜREN DİĞER ÖNEMLİ ŞAİRLER – II</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Epik-Tarihî ve Lirik Memleket Şairleri</text>\n  <text x="30" y="88" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Orhan Şaik Gökyay:</tspan> Epik <tspan font-weight="bold">"Bu Vatan Kimin?"</tspan></text>\n  <text x="38" y="102" font-size="9.5" fill="#1e3a8a">şiiri, <tspan font-style="italic">Dede Korkut</tspan> araştırmaları ve <tspan font-style="italic">Destursuz Bağa Girenler</tspan>.</text>\n  <text x="30" y="120" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Necmettin Halil Onan:</tspan> <tspan font-weight="bold">"Bir Yolcuya" (Dur Yolcu)</tspan></text>\n  <text x="38" y="134" font-size="9.5" fill="#1e3a8a">şiiri, <tspan font-style="italic">Çakıl Taşları</tspan>, <tspan font-style="italic">Bir Yudum Daha</tspan>.</text>\n  <text x="30" y="152" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Ömer Bedrettin Uşaklı ("Anadolu Şairi"):</tspan></text>\n  <text x="38" y="166" font-size="9.5" font-style="italic" fill="#1e3a8a">Deniz Sarhoşları, Yayla Dumanı, Sarıkız Mermerleri.</text>\n  <text x="30" y="184" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Zeki Ömer Defne:</tspan> "Yurt Güzellemeleri" ("Ilgaz",</text>\n  <text x="38" y="198" font-size="9.5" fill="#1e3a8a">"Ziller Çalacak"), <tspan font-style="italic">Denizden Çalınmış Ülke, Sessiz Nehir</tspan>.</text>\n  <text x="30" y="216" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">Behçet Kemal Çağlar:</tspan> <tspan font-style="italic">Erciyes\'ten Kopan Çığ</tspan>.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Destan ve Gelenek Şairleri (1950 Sonrası Dahil)</text>\n  <text x="370" y="90" font-size="10" fill="#14532d">• <tspan font-weight="bold">Niyazi Yıldırım Gençosmanoğlu (1929–1992):</tspan></text>\n  <text x="378" y="105" font-size="9.5" fill="#14532d">Cumhuriyet dönemi <tspan font-weight="bold">destan şairi</tspan>; Türk tarihini ve</text>\n  <text x="378" y="119" font-size="9.5" fill="#14532d">alperen ruhunu işledi (<tspan font-style="italic">Bozkurtların Ruhu, Malazgirt</tspan></text>\n  <text x="378" y="133" font-size="9.5" fill="#14532d"><tspan font-style="italic">Destanı, Kopuzdan Ezgiler, Salur Kazan Destanı</tspan>).</text>\n  <text x="370" y="155" font-size="10" fill="#14532d">• <tspan font-weight="bold">Bekir Sıtkı Erdoğan (1926–2014):</tspan></text>\n  <text x="378" y="170" font-size="9.5" fill="#14532d">Halk ve divan şiirini birleştirdi; ünlü <tspan font-weight="bold">"Binbirinci</tspan></text>\n  <text x="378" y="184" font-size="9.5" fill="#14532d"><tspan font-weight="bold">Gece" (Hancı)</tspan> şiiri, <tspan font-weight="bold">"50. Yıl Marşı"</tspan>, <tspan font-style="italic">Bir Yağmur</tspan></text>\n  <text x="378" y="198" font-size="9.5" fill="#14532d"><tspan font-style="italic">Başladı, Dostlar Başına, Kışlada Bahar</tspan>.</text>\n  <text x="370" y="220" font-size="10" fill="#14532d">• <tspan font-weight="bold">Dilaver Cebeci:</tspan> <tspan font-style="italic">Hun Aşkı</tspan>, "Türkiyem" şiiri.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
